// src/pages/admin/StoringProgressPage.js
// Menu Storing — unit yang sudah di-approve, assign mekanik, monitor progres

import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';

const PROGRES_LIST = [
  { value:'Menunggu Mekanik',     icon:'⏳', color:'#74777f', bg:'#f3f4f6' },
  { value:'Mekanik Ditugaskan',   icon:'👷', color:'#92400e', bg:'#fef3c7' },
  { value:'Mekanik Berangkat',    icon:'🚗', color:'#1e3a8a', bg:'#dbeafe' },
  { value:'Mekanik Tiba',         icon:'📍', color:'#4c1d95', bg:'#ede9fe' },
  { value:'Perbaikan Berlangsung',icon:'🔧', color:'#b45309', bg:'#fef9c3' },
  { value:'Selesai',              icon:'✅', color:'#065f46', bg:'#d1fae5' },
];

export default function StoringProgressPage() {
  const { profile }           = useAuth();
  const [list, setList]       = useState([]);
  const [loading, setLoad]    = useState(true);
  const [selected, setSelected] = useState(null);
  const [mekaniks, setMekaniks] = useState([]);
  const [form, setForm]       = useState({ mekanik_id:'', tgl_berangkat:'', jam_berangkat:'' });
  const [saving, setSaving]   = useState(false);
  const [logs, setLogs]       = useState([]);

  useEffect(() => {
    load();
    supabase.from('users').select('id,nama').eq('role','mekanik').then(({data}) => setMekaniks(data||[]));
  }, []);

  async function load() {
    const { data } = await supabase
      .from('storing')
      .select(`
        *,
        unit:units(nopol, tipe),
        driver:users!storing_driver_id_fkey(nama, no_hp),
        mekanik:users!storing_mekanik_id_fkey(nama)
      `)
      .in('status', ['Aktif','Pending'])
      .order('created_at', { ascending: false });
    setList(data || []);
    setLoad(false);
  }

  async function loadLogs(storingId) {
    const { data } = await supabase
      .from('storing_log')
      .select('*, user:users!storing_log_dibuat_oleh_fkey(nama)')
      .eq('storing_id', storingId)
      .order('created_at', { ascending: true });
    setLogs(data || []);
  }

  async function handleAssignMekanik() {
    if (!form.mekanik_id) { toast.error('Pilih mekanik dulu'); return; }
    setSaving(true);
    try {
      const progresLama = selected.progres;
      const { error } = await supabase.from('storing').update({
        mekanik_id:    form.mekanik_id,
        tgl_berangkat: form.tgl_berangkat || null,
        jam_berangkat: form.jam_berangkat || null,
        progres:       'Mekanik Ditugaskan',
      }).eq('id', selected.id);

      if (error) throw error;

      // Audit log
      await supabase.from('storing_log').insert({
        storing_id:  selected.id,
        status_lama: progresLama,
        status_baru: 'Mekanik Ditugaskan',
        catatan:     `Mekanik ditugaskan. Berangkat: ${form.tgl_berangkat || '-'} ${form.jam_berangkat || ''}`,
        dibuat_oleh: profile?.id,
      });

      // Notif ke driver
      await supabase.from('notifikasi').insert({
        user_id: selected.driver_id,
        judul:   '👷 Mekanik Ditugaskan',
        isi:     `Mekanik telah ditugaskan untuk kendaraan Anda. Jadwal berangkat: ${form.tgl_berangkat || 'Segera'} ${form.jam_berangkat || ''}`,
        tipe:    'storing',
      });

      toast.success('Mekanik berhasil ditugaskan!');
      setSelected(null);
      setForm({ mekanik_id:'', tgl_berangkat:'', jam_berangkat:'' });
      load();
    } catch(e) { toast.error('Gagal: '+e.message); }
    finally { setSaving(false); }
  }

  async function updateProgres(storing, progres) {
    setSaving(true);
    try {
      const progresLama = storing.progres;
      const { error } = await supabase.from('storing')
        .update({ progres, status: progres === 'Selesai' ? 'Selesai' : storing.status })
        .eq('id', storing.id);

      if (error) throw error;

      // Jika selesai → update unit kembali ke Standby Pool
      if (progres === 'Selesai') {
        await supabase.from('storing').update({
          status: 'Selesai',
          tgl_selesai: new Date().toISOString()
        }).eq('id', storing.id);
        await supabase.from('units').update({ status: 'Standby Pool' }).eq('id', storing.unit_id);
      }

      // Audit log
      await supabase.from('storing_log').insert({
        storing_id:  storing.id,
        status_lama: progresLama,
        status_baru: progres,
        dibuat_oleh: profile?.id,
      });

      toast.success(`Status diubah: ${progres}`);
      if (selected?.id === storing.id) {
        setSelected(prev => ({ ...prev, progres }));
        loadLogs(storing.id);
      }
      load();
    } catch(e) { toast.error('Gagal: '+e.message); }
    finally { setSaving(false); }
  }

  const getProgresStyle = (value) => PROGRES_LIST.find(p => p.value === value) || PROGRES_LIST[0];
  const getProgresIndex = (value) => PROGRES_LIST.findIndex(p => p.value === value);
  const getNextProgres  = (current) => {
    const idx = getProgresIndex(current);
    return idx < PROGRES_LIST.length - 1 ? PROGRES_LIST[idx + 1].value : null;
  };

  if (loading) return <div style={{ padding:40, textAlign:'center', color:'#74777f', fontFamily:'Montserrat,sans-serif' }}>Memuat...</div>;

  return (
    <div style={{ fontFamily:'Montserrat,sans-serif' }}>
      <h2 style={{ fontSize:18, fontWeight:700, marginBottom:4 }}>Menu Storing</h2>
      <p style={{ fontSize:11, color:'#74777f', marginBottom:16 }}>Unit yang sedang dalam proses storing — assign mekanik & monitor progres</p>

      {list.length === 0 ? (
        <div style={{ background:'#fff', border:'1px solid #ebeced', borderRadius:8, padding:40, textAlign:'center', color:'#c4c7cf' }}>
          Tidak ada unit storing aktif saat ini
        </div>
      ) : (
        <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
          {list.map(s => {
            const ps      = getProgresStyle(s.progres);
            const nextP   = getNextProgres(s.progres);
            const durasi  = s.tgl_mulai ? Math.floor((new Date() - new Date(s.tgl_mulai)) / (1000*60*60*24)) : 0;
            const isOver7 = durasi > 7;
            const isOver30= durasi > 30;

            return (
              <div key={s.id} style={{
                background:'#fff', borderRadius:8, padding:'14px 16px',
                border: isOver30 ? '1px solid #fca5a5' : isOver7 ? '1px solid #fcd34d' : '1px solid #ebeced',
                borderLeft: isOver30 ? '4px solid #ba1a1a' : isOver7 ? '4px solid #f59e0b' : '1px solid #ebeced',
              }}>
                <div style={{ display:'flex', alignItems:'flex-start', justifyContent:'space-between', gap:12, flexWrap:'wrap' }}>
                  <div style={{ flex:1 }}>
                    {/* Header */}
                    <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:8, flexWrap:'wrap' }}>
                      <span style={{ fontWeight:700, fontFamily:'monospace', fontSize:13 }}>{s.unit?.nopol}</span>
                      <span style={{ background:ps.bg, color:ps.color, padding:'2px 8px', borderRadius:20, fontSize:10, fontWeight:700 }}>
                        {ps.icon} {s.progres}
                      </span>
                      {isOver30 && <span style={{ background:'#fee2e2', color:'#7f1d1d', padding:'2px 8px', borderRadius:20, fontSize:10, fontWeight:700 }}>⚠ {durasi} hari</span>}
                      {isOver7 && !isOver30 && <span style={{ background:'#fef3c7', color:'#92400e', padding:'2px 8px', borderRadius:20, fontSize:10, fontWeight:700 }}>⚠ {durasi} hari</span>}
                    </div>

                    <p style={{ fontSize:11, color:'#44474e', marginBottom:2 }}>
                      Driver: <b>{s.driver?.nama}</b> · {s.driver?.no_hp}
                    </p>
                    <p style={{ fontSize:11, color:'#44474e', marginBottom:2 }}>
                      Mekanik: <b>{s.mekanik?.nama || <span style={{ color:'#ba1a1a' }}>Belum ditugaskan</span>}</b>
                    </p>
                    {s.tgl_berangkat && (
                      <p style={{ fontSize:11, color:'#74777f' }}>
                        Jadwal: {s.tgl_berangkat} {s.jam_berangkat || ''}
                      </p>
                    )}

                    {/* Progress bar */}
                    <div style={{ marginTop:10 }}>
                      <div style={{ display:'flex', gap:3 }}>
                        {PROGRES_LIST.map((p, i) => {
                          const currentIdx = getProgresIndex(s.progres);
                          return (
                            <div key={i} style={{ flex:1, height:4, borderRadius:2,
                              background: i <= currentIdx ? '#1a2b4b' : '#e5e7eb'
                            }}/>
                          );
                        })}
                      </div>
                      <div style={{ display:'flex', justifyContent:'space-between', marginTop:4 }}>
                        <span style={{ fontSize:9, color:'#74777f' }}>Mulai</span>
                        <span style={{ fontSize:9, color:'#74777f' }}>Selesai</span>
                      </div>
                    </div>
                  </div>

                  {/* Actions */}
                  <div style={{ display:'flex', flexDirection:'column', gap:6, minWidth:120 }}>
                    {/* Assign mekanik jika belum */}
                    {!s.mekanik_id && (
                      <button onClick={() => { setSelected(s); setForm({ mekanik_id:'', tgl_berangkat:'', jam_berangkat:'' }); }}
                        style={{ background:'#1a2b4b', color:'#fff', border:'none', borderRadius:6, padding:'6px 12px', fontSize:11, fontWeight:700, cursor:'pointer' }}>
                        👷 Assign Mekanik
                      </button>
                    )}

                    {/* Update progres */}
                    {nextP && s.progres !== 'Selesai' && (
                      <button onClick={() => updateProgres(s, nextP)} disabled={saving}
                        style={{ background:'#10b981', color:'#fff', border:'none', borderRadius:6, padding:'6px 12px', fontSize:11, fontWeight:700, cursor:'pointer' }}>
                        {getProgresStyle(nextP).icon} {nextP}
                      </button>
                    )}

                    {/* Lihat log */}
                    <button onClick={() => { setSelected(s); loadLogs(s.id); }}
                      style={{ background:'#fff', color:'#1a2b4b', border:'1px solid #c4c7cf', borderRadius:6, padding:'5px 12px', fontSize:11, fontWeight:600, cursor:'pointer' }}>
                      📋 Detail
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal Detail & Assign */}
      {selected && (
        <div style={{ position:'fixed', inset:0, background:'rgba(0,0,0,0.5)', zIndex:50, display:'flex', alignItems:'center', justifyContent:'center', padding:16 }}>
          <div style={{ background:'#fff', borderRadius:12, width:'100%', maxWidth:480, maxHeight:'90vh', overflowY:'auto' }}>
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', padding:'16px 20px', borderBottom:'1px solid #ebeced' }}>
              <h3 style={{ fontSize:15, fontWeight:700 }}>Storing — {selected.unit?.nopol}</h3>
              <button onClick={() => { setSelected(null); setLogs([]); }} style={{ background:'none', border:'none', fontSize:20, cursor:'pointer', color:'#74777f' }}>×</button>
            </div>

            <div style={{ padding:20 }}>
              {/* Status progres */}
              <div style={{ marginBottom:16 }}>
                <p style={{ fontSize:10, fontWeight:700, color:'#74777f', textTransform:'uppercase', marginBottom:8 }}>Progres Storing</p>
                <div style={{ display:'flex', flexDirection:'column', gap:4 }}>
                  {PROGRES_LIST.map((p, i) => {
                    const currentIdx = getProgresIndex(selected.progres);
                    const isDone     = i < currentIdx;
                    const isCurrent  = i === currentIdx;
                    return (
                      <div key={i} style={{ display:'flex', alignItems:'center', gap:10, padding:'8px 10px', borderRadius:8,
                        background: isCurrent ? p.bg : isDone ? '#f0fdf4' : '#f9fafb',
                        border: isCurrent ? `1px solid ${p.color}20` : '1px solid transparent'
                      }}>
                        <span style={{ fontSize:16 }}>{isDone ? '✅' : p.icon}</span>
                        <span style={{ fontSize:12, fontWeight: isCurrent ? 700 : 500, color: isCurrent ? p.color : isDone ? '#065f46' : '#9ca3af' }}>
                          {p.value}
                        </span>
                        {isCurrent && <span style={{ marginLeft:'auto', fontSize:10, background:p.bg, color:p.color, padding:'2px 8px', borderRadius:20, fontWeight:700 }}>Saat ini</span>}
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* Assign mekanik */}
              {!selected.mekanik_id && (
                <div style={{ background:'#fffbeb', border:'1px solid #fcd34d', borderRadius:10, padding:14, marginBottom:16 }}>
                  <p style={{ fontSize:12, fontWeight:700, color:'#92400e', marginBottom:12 }}>👷 Tugaskan Mekanik</p>
                  <div style={{ marginBottom:10 }}>
                    <label style={{ display:'block', fontSize:10, fontWeight:700, color:'#44474e', textTransform:'uppercase', marginBottom:4 }}>Mekanik</label>
                    <select value={form.mekanik_id} onChange={e => setForm(p=>({...p,mekanik_id:e.target.value}))}
                      style={{ width:'100%', border:'1px solid #c4c7cf', borderRadius:8, padding:'8px 10px', fontSize:12, fontFamily:'Montserrat,sans-serif', outline:'none' }}>
                      <option value="">-- Pilih Mekanik --</option>
                      {mekaniks.map(m => <option key={m.id} value={m.id}>{m.nama}</option>)}
                    </select>
                  </div>
                  <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:10, marginBottom:10 }}>
                    <div>
                      <label style={{ display:'block', fontSize:10, fontWeight:700, color:'#44474e', textTransform:'uppercase', marginBottom:4 }}>Tgl Berangkat</label>
                      <input type="date" value={form.tgl_berangkat} onChange={e => setForm(p=>({...p,tgl_berangkat:e.target.value}))}
                        style={{ width:'100%', border:'1px solid #c4c7cf', borderRadius:8, padding:'8px 10px', fontSize:12, fontFamily:'Montserrat,sans-serif', outline:'none', boxSizing:'border-box' }}/>
                    </div>
                    <div>
                      <label style={{ display:'block', fontSize:10, fontWeight:700, color:'#44474e', textTransform:'uppercase', marginBottom:4 }}>Jam Berangkat</label>
                      <input type="time" value={form.jam_berangkat} onChange={e => setForm(p=>({...p,jam_berangkat:e.target.value}))}
                        style={{ width:'100%', border:'1px solid #c4c7cf', borderRadius:8, padding:'8px 10px', fontSize:12, fontFamily:'Montserrat,sans-serif', outline:'none', boxSizing:'border-box' }}/>
                    </div>
                  </div>
                  <button onClick={handleAssignMekanik} disabled={saving}
                    style={{ width:'100%', background:saving?'#9ca3af':'#1a2b4b', color:'#fff', border:'none', borderRadius:8, padding:'10px 0', fontSize:12, fontWeight:700, cursor:'pointer', fontFamily:'Montserrat,sans-serif' }}>
                    {saving ? 'Menyimpan...' : 'Tugaskan Mekanik'}
                  </button>
                </div>
              )}

              {/* Audit Log */}
              {logs.length > 0 && (
                <div>
                  <p style={{ fontSize:10, fontWeight:700, color:'#74777f', textTransform:'uppercase', marginBottom:8 }}>Audit Log</p>
                  <div style={{ display:'flex', flexDirection:'column', gap:6 }}>
                    {logs.map((log, i) => (
                      <div key={i} style={{ display:'flex', gap:10, padding:'8px 10px', background:'#f8f9fa', borderRadius:8 }}>
                        <div style={{ width:6, height:6, borderRadius:'50%', background:'#1a2b4b', marginTop:4, flexShrink:0 }}/>
                        <div>
                          <p style={{ fontSize:11, fontWeight:600 }}>
                            {log.status_lama ? `${log.status_lama} → ` : ''}{log.status_baru}
                          </p>
                          {log.catatan && <p style={{ fontSize:10, color:'#74777f' }}>{log.catatan}</p>}
                          <p style={{ fontSize:10, color:'#c4c7cf' }}>
                            {log.user?.nama} · {new Date(log.created_at).toLocaleString('id-ID')}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
